import { Component, h, Prop, Host, Element, State, Event, EventEmitter } from '@stencil/core';
import { throttle } from 'lodash-es';
import classNames from 'classnames';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendActionTracking, sendDurationTracking, sendExposeTracking } from '@src/shared/unclassified/tracking';
import { searchMessages } from '@fe-infra/keystone-locales';
import { t } from '@src/shared/i18n';
import { Vue2ValueFix, Uncontrollable } from '@src/framework/decorators';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { FormContextValueReconcile } from '@src/components/ks-form/FormContextValueReconcile';
import { getPartProps } from '@src/shared/base-props';
import { CategoryItem, SearchStatus, SearchPartProps } from './types';
import { KsIconSearch } from '@fe-infra/keystone-icons-stencil';

const prefix = 'search';

/**
 * Search helps people query content with optional categories and suggestions.
 *
 * @part base - The outer container that groups the category selector and search input.
 * @part categorySelect - The category select component.
 * @part suggestionDropdown - The suggestion dropdown component.
 * @part input - The input component.
 * @part inputBase - The base part of the input component.
 */
@Component({
  tag: 'ks-search',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsSearch extends FormBaseComponent<string> {
  protected static vModel = { prop: 'value', event: 'ksChange' };

  @Element() el!: HTMLKsSearchElement;
  private ksInputEl?: HTMLKsInputElement;

  /** The current input value of the search box. */
  @Prop() @Vue2ValueFix() @FormContextValueReconcile() value?: string;
  /** The initial input value when the search box is used in uncontrolled mode. */
  @Prop() defaultValue?: string;

  @Uncontrollable('value', 'defaultValue', 'ksChange') @State() internalValueState?: string;

  /** Indicates whether the search box is disabled. When `true`, the search box will be inactive. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;
  /** The placeholder text displayed in the search input field when it is empty. */
  @Prop() placeholder?: string;
  /** The placeholder text for the category dropdown, displayed when no category is selected. */
  @Prop() categoryPlaceholder?: string;
  /** A list of categories that users can choose from. */
  @Prop() categories?: CategoryItem[];

  /** The selected category value when the search box is used in controlled mode. */
  @Prop() selectedCategory?: string | number;
  /** The initial selected category when the search box is used in uncontrolled mode. */
  @Prop() defaultSelectedCategory?: string | number;

  @Uncontrollable('selectedCategory', 'defaultSelectedCategory', 'ksCategoryChange')
  @State()
  internalSelectedCategoryState?: string | number;

  /** The validation status of the search input. Can be `"default"`, `"warning"`, or `"error"`. */
  @Prop() @FormContextValueReconcile() status?: SearchStatus;
  /** A list of suggestions to display as the user types in the search box. */
  @Prop() suggestions?: string[];
  /** Indicates whether the input field can be cleared by the user. When `true`, a clear button is displayed to clear the input value. */
  @Prop() clearable = false;

  /** The width of the category select dropdown. Can be a string (e.g., "100px", "50%") or a number (in pixels). */
  @Prop() selectWidth?: string | number;

  /** Pass props through to the inner `categorySelect`, `suggestionDropdown`, and `input` parts. */
  @Prop() partProps?: SearchPartProps;

  /** Triggered when the input value changes, including typing and suggestion selection. Emits the current value. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<string>;

  /** Triggered when users press Enter in the input. Emits the current value. */
  @Event({ bubbles: false, composed: false }) ksSearch!: EventEmitter<string>;
  /** Triggered when users clear the input with the built-in clear action. */
  @Event({ bubbles: false, composed: false }) ksClear!: EventEmitter<void>;

  /** Triggered when the selected category changes. Emits the selected category value. */
  @Event({ bubbles: false, composed: false }) ksCategoryChange!: EventEmitter<string | number>;

  @State() isInputFocused = false;

  constructor() {
    super();
    registerPluginManager(this.el);
  }

  private handleInput = ({ detail }: CustomEvent<string>) => {
    this.internalValueState = detail;
    throttle(() => sendActionTracking(this.el, { eventType: 'change', componentParams: { value: detail } }), 500);
  };
  private handleInputFocus = () => {
    this.isInputFocused = true;
    sendActionTracking(this.el, { eventType: 'focus' });
  };
  private handleInputBlur = () => {
    this.isInputFocused = false;
    sendActionTracking(this.el, { eventType: 'blur' });
  };

  private onInputKeyup = (event: KeyboardEvent) => {
    if (['Enter', 'NumpadEnter'].includes(event.code)) {
      this.ksSearch.emit(this.internalValueState);
      sendActionTracking(this.el, { eventType: 'confirm', componentParams: { value: this.internalValueState } });
    }
  };

  render() {
    const cls = classNames(prefix, { [`${prefix}__disabled`]: this.disabled });
    return (
      <Host class="KsSearch">
        <ks-space class={cls} compact part="base">
          {this.categories?.length && (
            <ks-select
              part="categorySelect"
              class={`${prefix}__select`}
              value={this.internalSelectedCategoryState}
              placeholder={this.categoryPlaceholder}
              disabled={this.disabled}
              options={this.categories.map(({ value, label, disabled }) => ({
                value,
                label,
                disabled,
              }))}
              style={{
                width:
                  typeof this.selectWidth === 'string'
                    ? this.selectWidth
                    : this.selectWidth !== undefined
                      ? `${this.selectWidth}px`
                      : undefined,
              }}
              onKsOpenChange={({ detail }) => {
                if (detail) {
                  sendExposeTracking(this.el, { eventType: 'popup', subEventType: 'category' });
                  sendDurationTracking(this.el, { eventType: 'popup', subEventType: 'category', reset: true });
                } else {
                  sendDurationTracking(this.el, { eventType: 'popup', subEventType: 'category' });
                }
              }}
              onKsChange={({ detail }) => {
                this.internalSelectedCategoryState = detail[0] as string | number;
              }}
              data-testid="ks-search-index-nT4bhG"
              {...getPartProps(this, 'categorySelect')}
            />
          )}

          <ks-dropdown-menu
            class={`${prefix}__input`}
            open={Boolean(this.suggestions?.length && this.isInputFocused)}
            options={
              this.suggestions?.map((suggestion) => ({
                label: suggestion,
                value: suggestion,
                disabled: false,
              })) ?? []
            }
            search={{ hideSearchInput: true }}
            searchValue={this.internalValueState}
            onKsOpenChange={({ detail }) => {
              if (detail) {
                sendExposeTracking(this.el, { eventType: 'popup', subEventType: 'suggestion' });
                sendDurationTracking(this.el, { eventType: 'popup', subEventType: 'suggestion', reset: true });
              } else {
                sendDurationTracking(this.el, { eventType: 'popup', subEventType: 'suggestion' });
              }
            }}
            selectable={false}
            onKsChange={({ detail }) => {
              const value = detail[0][0] as string;
              this.internalValueState = value;
              sendActionTracking(this.el, {
                eventType: 'change',
                subEventType: 'suggestion',
                componentParams: { value },
              });
            }}
            data-testid="ks-search-index-cGeD77"
            {...getPartProps(this, 'suggestionDropdown')}
          >
            <ks-input
              ref={(el) => (this.ksInputEl = el)}
              value={this.internalValueState}
              placeholder={this.placeholder || t(searchMessages.placeholder)}
              status={this.status}
              onKsFocus={this.handleInputFocus}
              onKsBlur={this.handleInputBlur}
              disabled={this.disabled}
              onKsChange={this.handleInput}
              onKeyUp={this.onInputKeyup}
              onKsClear={() => {
                this.ksClear.emit();
              }}
              clearable={this.clearable}
              data-testid="ks-search-index-muL9Zv"
              exportparts="base: inputBase"
              {...getPartProps(this, 'input')}
            >
              {!this.isInputFocused && !this.internalValueState && !this.ksInputEl?.value && (
                <KsIconSearch id="search-icon" size={16} slot="prefix" />
              )}
            </ks-input>
          </ks-dropdown-menu>
        </ks-space>
      </Host>
    );
  }
}
